+    commands.splice(0, commands.length);
+    ctx.isFlushingDeferred = true;
+    try {
+        // A spawn followed by a destroy has no externally observable structural work.
+        const nullified = new Set<Entity>();
+        const spawned = new Set<Entity>();
+        for (const command of commands) {
+            if (command.type === 'spawn') spawned.add(command.entity);
+            if (command.type === 'destroy' && spawned.has(command.entity)) nullified.add(command.entity);
+        }
+        for (const command of commands) {
+            if (nullified.has(command.entity)) {
+                if (command.type === 'destroy' && world.has(command.entity)) destroyEntity(world, command.entity);
+                continue;
+            }
+            if (command.type === 'spawn') {
+                if (!world.has(command.entity)) continue;
+                if (command.traits.length) addTrait(world, command.entity, ...command.traits);
+                continue;
+            }
