+type SubscriptionSnapshot = Map<Trait, Set<string>>;
+function snapshotSubscriptions(world: World): SubscriptionSnapshot {
+    const snapshot: SubscriptionSnapshot = new Map();
+    const ctx = world[$internal];
+    for (const entity of world.entities) {
+        for (const trait of ctx.entityTraits.get(entity) ?? []) {
+            const instance = ctx.traitInstances[trait.id];
+            if (!instance || (!instance.addSubscriptions.size && !instance.removeSubscriptions.size)) continue;
+            let values = snapshot.get(trait);
+            if (!values) snapshot.set(trait, (values = new Set()));
+            const relation = trait[$internal].relation;
+            if (relation) for (const target of getRelationTargets(world, relation, entity)) values.add(`${entity}:${target}`);
+            else values.add(`${entity}`);
+        }
+    }
+    return snapshot;
+}
+function dispatchSubscriptionDifference(world: World, before: SubscriptionSnapshot) {
+    const after = snapshotSubscriptions(world);
+    const traits = new Set([...before.keys(), ...after.keys()]);
+    for (const trait of traits) {
+        const instance = world[$internal].traitInstances[trait.id];
+        if (!instance) continue;
+        const oldValues = before.get(trait) ?? new Set<string>();
+        const newValues = after.get(trait) ?? new Set<string>();
